#include <stdio.h>

void double_all(int a[], int n) {
    for (int i = 0; i < n; i++) {
        a[i] = a[i] * 2;
    }
}

void triple_all(int a[], int n) {
    for (int i = 0; i < n; i++) {
        a[i] = a[i] * 3;
    }
}

int main() {
    int a[] = {1, 2, 3, 4};
    double_all(a, 4);
    triple_all(a, 4);
    for (int i = 0; i < 4; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}

