#include <stdio.h>

void scale(int a[], int n, int factor) {
    for (int i = 0; i < n; i++) {
        a[i] *= factor;
    }
}

int main() {
    int a[] = {1, 2, 3, 4};
    scale(a, 4, 2);
    scale(a, 4, 3);
    for (int i = 0; i < 4; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}
